    descriptionAdvanced: {
      de: "Der Khalifa Port ist das maritime Flaggschiffprojekt von Abu Dhabi und einer der modernsten Tiefwasserhäfen der Welt. Er wurde auf einer künstlichen Insel etwa vier Kilometer vor der Küste von Taweelah errichtet und im Dezember 2012 offiziell eröffnet. Der Hafen wurde konzipiert, um den historischen Hafen Mina Zayed zu entlasten und das massive Wirtschaftswachstum des Emirats zu unterstützen. Khalifa Port ist bekannt für sein semi-automatisiertes Containerterminal, das zu den technologisch fortschrittlichsten Anlagen weltweit gehört und eine hocheffiziente Abfertigung ermöglicht. Er ist direkt mit der Khalifa Economic Zones Abu Dhabi (KEZAD) verbunden, dem größten Industrie- und Logistikzentrum der Region, das eine integrierte Handelsplattform bietet. Der Hafen spielt eine zentrale Rolle in der „Belt and Road Initiative“ durch die Partnerschaft mit COSCO Shipping, was ihn zu einem wichtigen Knotenpunkt für den Handel zwischen China und dem Nahen Osten macht. Die Infrastruktur umfasst spezialisierte Terminals für Aluminiumexporte (Emirates Global Aluminium), Roll-on/Roll-off-Ladung und Flüssiggut.",
      hu: "Khalifa Port Abu Dhabi tengeri zászlóshajó-projektje és a világ egyik legmodernebb mélyvízi kikötője. Egy mesterséges szigeten épült, körülbelül négy kilométerre a parttól Taweelah-nál, és hivatalosan 2012 decemberében nyitották meg. A kikötőt azért hozták létre, hogy tehermentesítse a történelmi Mina Zayed kikötőt, és támogassa az emírség hatalmas gazdasági növekedését. Khalifa Port híres félig automatizált konténertermináljáról, amely a világ technológiailag legfejlettebb létesítményei közé tartozik, és rendkívül hatékony árukezelést tesz lehetővé. Közvetlen összeköttetésben áll a Khalifa Gazdasági Övezettel (KEZAD), amely a régió legnagyobb ipari és logisztikai központja, integrált kereskedelmi platformot kínálva. A kikötő központi szerepet játszik az „Egy övezet, egy út” kezdeményezésben a COSCO Shippinggel való partnerség révén, ami Kína és a Közel-Kelet közötti kereskedelem kulcsfontosságú csomópontjává teszi. Az infrastruktúra speciális terminálokat foglal magában az alumíniumexport (Emirates Global Aluminium), a Ro-Ro rakományok és a folyékony áruk számára.",
      ro: "Portul Khalifa este proiectul maritim emblematic al emiratului Abu Dhabi și unul dintre cele mai moderne porturi de mare adâncime din lume. Construit pe o insulă artificială la aproximativ patru kilometri de coasta Taweelah, portul a fost inaugurat oficial în decembrie 2012. Acesta a fost conceput pentru a prelua traficul de la portul istoric Mina Zayed și pentru a susține creșterea economică masivă a emiratului. Portul Khalifa este renumit pentru terminalul său de containere semi-automatizat, care se numără printre cele mai avansate tehnologic facilități la nivel mondial, permițând o procesare extrem de eficientă. Este conectat direct la Zonele Economice Khalifa Abu Dhabi (KEZAD), cel mai mare centru industrial și logistic din regiune. Portul joacă un rol central în inițiativa „Belt and Road” prin parteneriatul cu COSCO Shipping, devenind un nod vital pentru comerțul dintre China și Orientul Mijlociu. Infrastructura sa include terminale specializate pentru exportul de aluminiu (Emirates Global Aluminium), mărfuri Ro-Ro și produse lichide.",
      en: "Khalifa Port is Abu Dhabi's maritime flagship and ranks among the most advanced deep-water ports globally. Constructed on an artificial island approximately four kilometers offshore from Taweelah, it was officially inaugurated in December 2012. The port was engineered to succeed the historic Mina Zayed port and to provide the infrastructure necessary for the emirate's rapid economic diversification. Khalifa Port is distinguished by its semi-automated container terminal, utilizing state-of-the-art technology to ensure high operational efficiency and rapid vessel turnaround. It serves as the primary gateway for the Khalifa Economic Zones Abu Dhabi (KEZAD), the region's largest integrated industrial and logistics hub. The port is a critical node in the global 'Belt and Road Initiative' through its partnership with COSCO Shipping, solidifying its role in trade between China and the Middle East. Specialized facilities cater to major industrial players like Emirates Global Aluminium, alongside dedicated Ro-Ro and liquid bulk terminals.",
      es: "El puerto de Khalifa, inaugurado en 2012, es un puerto de aguas profundas en Abu Dabi, situado a unos 50 kilómetros al noreste de la ciudad. Forma parte de la Khalifa Industrial Zone Abu Dhabi (KIZAD) y fue diseñado como uno de los puertos tecnológicamente más avanzados del mundo. Con una capacidad inicial de 2,5 millones de TEU y una profundidad de agua de 16,5 metros, puede recibir a los portacontenedores más grandes. El puerto utiliza grúas automatizadas y un sistema inteligente de gestión del tráfico. Es un nodo central para el comercio con Asia y Europa y sirve como centro para la industria del petróleo y el gas. Está prevista la ampliación hasta una capacidad de 5 millones de TEU. El puerto de Khalifa es una parte importante de la diversificación económica de Abu Dabi.",
      pt: "O porto de Khalifa, inaugurado em 2012, é um porto de águas profundas em Abu Dhabi, situado a cerca de 50 quilómetros a nordeste da cidade. Faz parte da Khalifa Industrial Zone Abu Dhabi (KIZAD) e foi concebido como um dos portos tecnologicamente mais avançados do mundo. Com uma capacidade inicial de 2,5 milhões de TEU e uma profundidade de água de 16,5 metros, pode receber os maiores navios porta-contentores. O porto utiliza gruas automatizadas e um sistema inteligente de gestão de tráfego. É um nó central para o comércio com a Ásia e a Europa e serve como centro para a indústria petrolífera e de gás. Está planeada a expansão para uma capacidade de 5 milhões de TEU. O porto de Khalifa é uma parte importante da diversificação económica de Abu Dhabi.",
      fr: "Le port de Khalifa, inauguré en 2012, est un port en eau profonde à Abou Dabi, situé à environ 50 kilomètres au nord-est de la ville. Il fait partie de la Khalifa Industrial Zone Abu Dhabi (KIZAD) et a été conçu comme l'un des ports technologiquement les plus avancés au monde. Avec une capacité initiale de 2,5 millions d'EVP et une profondeur d'eau de 16,5 mètres, il peut accueillir les plus grands porte-conteneurs. Le port utilise des grues automatisées et un système intelligent de gestion du trafic. C'est un pôle central pour le commerce avec l'Asie et l'Europe et sert de plaque tournante pour l'industrie pétrolière et gazière. Une extension à une capacité de 5 millions d'EVP est prévue. Le port de Khalifa est un élément important de la diversification économique d'Abou Dabi.",
    },
