      hu: ["2012.12.12-én avatta fel Khalifa bin Zayed Al Nahyan sejk.", "A konténerterminál félig automatizált technológiával működik.", "Egy 2,7 négyzetkilométeres mesterséges szigeten helyezkedik el.", "A régió egyik leghosszabb hídja köti össze a szárazfölddel.", "A COSCO Shipping közel-keleti fő logisztikai csomópontja.", "Közvetlen kapcsolattal rendelkezik a KEZAD ipari övezethez."],
