      en: ["Inaugurated on the symbolic date of 12/12/12 by Sheikh Khalifa.", "Features the region's first semi-automated container terminal.", "Built on a 2.7-square-kilometer reclaimed artificial island.", "Connected to the mainland by a massive 1-kilometer-long bridge.", "Key regional hub for China's COSCO Shipping under 'Belt and Road'.", "Directly serves KEZAD, the largest industrial zone in Abu Dhabi."],
      es: ["Inaugurado en 2012", "Capacidad de 2,5 millones de TEU", "Profundidad de agua de 16,5 metros", "Parte de KIZAD", "50 km al noreste de Abu Dabi", "Capacidad planificada de 5 millones de TEU"],
      pt: ["Inaugurado em 2012", "Capacidade de 2,5 milhões de TEU", "Profundidade de água de 16,5 metros", "Parte da KIZAD", "50 km a nordeste de Abu Dhabi", "Capacidade planeada de 5 milhões de TEU"],
      fr: ["Inauguré en 2012", "Capacité de 2,5 millions d'EVP", "Profondeur d'eau de 16,5 mètres", "Fait partie de KIZAD", "50 km au nord-est d'Abou Dabi", "Capacité prévue de 5 millions d'EVP"],
