      en: ["The port was officially inaugurated in 1972 in Abu Dhabi city.", "Features a total of 21 berths across a land area of 5.3 square kilometers.", "Home to the award-winning Abu Dhabi Cruise Terminal since 2015.", "Relocated its entire container traffic to Khalifa Port in 2012.", "Currently serves as the main hub for vehicle imports (Ro-Ro traffic).", "Hosts Abu Dhabi's traditional fish market and the famous carpet souq."],
      es: ["Inaugurado en 1968", "7 atracaderos", "Barcos de hasta 240 metros de eslora", "Hoy para pasajeros y cruceros", "Ubicación en el centro de la ciudad en la Corniche", "Modernizado para el turismo"],
      pt: ["Inaugurado em 1968", "7 cais", "Navios até 240 metros de comprimento", "Hoje para passageiros e cruzeiros", "Localização no centro da cidade na Corniche", "Modernizado para o turismo"],
