      es: ["Capacidad de 100 MW", "En funcionamiento desde 2013", "Primera central CSP en Oriente Medio", "Reduce 175.000 toneladas de CO2 al año", "Superficie de 2,5 km²", "768 colectores de canales parabólicos"],
